Dataspatium.assets.register("presets/api/riksbanken-swea.api.json","text","{\n \"format\": \"dataspatium-api/1\",\n \"id\": \"riksbanken-swea\",\n \"name\": \"Riksbanken räntor och valutakurser (SWEA)\",\n \"publisher\": \"Sveriges riksbank\",\n \"description\": \"Styrräntan, marknadsräntor och valutakurser från Riksbankens SWEA-API: en lista över serierna, observationerna för en serie under en period, den senaste observationen och korskurser mellan två valutor.\",\n \"docs\": \"https://www.riksbank.se/sv/statistik/rantor-och-valutakurser/\",\n \"license\": {\n  \"name\": \"Fri användning med källangivelse (Riksbanken)\",\n  \"url\": \"https://www.riksbank.se/sv/statistik/\"\n },\n \"level\": 1,\n \"country\": \"SE\",\n \"baseUrl\": \"https://api.riksbank.se/swea/v1\",\n \"auth\": {\n  \"type\": \"none\"\n },\n \"rateLimit\": {\n  \"requests\": 1,\n  \"perSeconds\": 2\n },\n \"cors\": {\n  \"file\": false,\n  \"web\": false\n },\n \"endpoints\": [\n  {\n   \"id\": \"serier\",\n   \"name\": \"Serier\",\n   \"description\": \"Alla serier med id, beskrivning, grupp och period.\",\n   \"method\": \"GET\",\n   \"path\": \"/Series\",\n   \"response\": {\n    \"format\": \"json\"\n   },\n   \"dataset\": {\n    \"name\": \"Riksbanken serier\"\n   }\n  },\n  {\n   \"id\": \"observationer\",\n   \"name\": \"Observationer för en serie\",\n   \"description\": \"Värdena för en serie från ett datum, till ett datum eller till i dag.\",\n   \"method\": \"GET\",\n   \"path\": \"/Observations/{seriesId}/{from}/{to}\",\n   \"params\": [\n    {\n     \"name\": \"seriesId\",\n     \"in\": \"path\",\n     \"label\": \"Serie\",\n     \"type\": \"string\",\n     \"required\": true,\n     \"example\": \"SECBREPOEFF\",\n     \"optionsFrom\": {\n      \"endpoint\": \"serier\",\n      \"value\": \"seriesId\",\n      \"label\": \"shortDescription\"\n     }\n    },\n    {\n     \"name\": \"from\",\n     \"in\": \"path\",\n     \"label\": \"Från datum\",\n     \"type\": \"date\",\n     \"required\": true,\n     \"example\": \"2024-01-01\"\n    },\n    {\n     \"name\": \"to\",\n     \"in\": \"path\",\n     \"label\": \"Till datum\",\n     \"type\": \"date\",\n     \"help\": \"Tomt = till i dag.\"\n    }\n   ],\n   \"response\": {\n    \"format\": \"json\"\n   },\n   \"dataset\": {\n    \"name\": \"Riksbanken {seriesId}\"\n   }\n  },\n  {\n   \"id\": \"senaste\",\n   \"name\": \"Senaste observationen\",\n   \"method\": \"GET\",\n   \"path\": \"/Observations/Latest/{seriesId}\",\n   \"params\": [\n    {\n     \"name\": \"seriesId\",\n     \"in\": \"path\",\n     \"label\": \"Serie\",\n     \"type\": \"string\",\n     \"required\": true,\n     \"example\": \"SEKEURPMI\",\n     \"optionsFrom\": {\n      \"endpoint\": \"serier\",\n      \"value\": \"seriesId\",\n      \"label\": \"shortDescription\"\n     }\n    }\n   ],\n   \"response\": {\n    \"format\": \"json\"\n   },\n   \"dataset\": {\n    \"name\": \"Riksbanken {seriesId} senaste\"\n   }\n  },\n  {\n   \"id\": \"korskurser\",\n   \"name\": \"Korskurser\",\n   \"description\": \"Kursen mellan två valutor räknad ur deras kurser mot kronan.\",\n   \"method\": \"GET\",\n   \"path\": \"/CrossRates/{series1}/{series2}/{from}/{to}\",\n   \"params\": [\n    {\n     \"name\": \"series1\",\n     \"in\": \"path\",\n     \"label\": \"Första valutan\",\n     \"type\": \"string\",\n     \"required\": true,\n     \"example\": \"SEKEURPMI\"\n    },\n    {\n     \"name\": \"series2\",\n     \"in\": \"path\",\n     \"label\": \"Andra valutan\",\n     \"type\": \"string\",\n     \"required\": true,\n     \"example\": \"SEKUSDPMI\"\n    },\n    {\n     \"name\": \"from\",\n     \"in\": \"path\",\n     \"label\": \"Från datum\",\n     \"type\": \"date\",\n     \"required\": true,\n     \"example\": \"2024-01-01\"\n    },\n    {\n     \"name\": \"to\",\n     \"in\": \"path\",\n     \"label\": \"Till datum\",\n     \"type\": \"date\",\n     \"help\": \"Tomt = till i dag.\"\n    }\n   ],\n   \"response\": {\n    \"format\": \"json\"\n   },\n   \"dataset\": {\n    \"name\": \"Riksbanken {series1}/{series2}\"\n   }\n  }\n ],\n \"notes\": \"Tjänsten tillåter inte anrop från webbläsaren (ingen CORS), så den nås bara via bryggan: starta bryggan med --allow-host api.riksbank.se (-AllowHosts api.riksbank.se i PowerShell), anslut den under Inhämta och slå på Hämta via bryggan i Internetåtkomst.\",\n \"i18n\": {\n  \"en\": {\n   \"name\": \"Riksbank interest and exchange rates (SWEA)\",\n   \"publisher\": \"Sveriges Riksbank\",\n   \"description\": \"The policy rate, market rates and exchange rates from the Riksbank’s SWEA API: a list of the series, the observations of a series over a period, the latest observation and cross rates between two currencies.\",\n   \"notes\": \"The service does not allow requests from the browser (no CORS), so it is reached only through the bridge: start the bridge with --allow-host api.riksbank.se (-AllowHosts api.riksbank.se in PowerShell), connect it under Import and turn on Fetch through the bridge in Internet access.\",\n   \"endpoints\": {\n    \"serier\": {\n     \"name\": \"Series\"\n    },\n    \"observationer\": {\n     \"name\": \"Observations of a series\",\n     \"params\": {\n      \"seriesId\": {\n       \"label\": \"Series\"\n      },\n      \"from\": {\n       \"label\": \"From date\"\n      },\n      \"to\": {\n       \"label\": \"To date\",\n       \"help\": \"Empty = until today.\"\n      }\n     }\n    },\n    \"senaste\": {\n     \"name\": \"Latest observation\",\n     \"params\": {\n      \"seriesId\": {\n       \"label\": \"Series\"\n      }\n     }\n    },\n    \"korskurser\": {\n     \"name\": \"Cross rates\",\n     \"params\": {\n      \"series1\": {\n       \"label\": \"First currency\"\n      },\n      \"series2\": {\n       \"label\": \"Second currency\"\n      },\n      \"from\": {\n       \"label\": \"From date\"\n      },\n      \"to\": {\n       \"label\": \"To date\",\n       \"help\": \"Empty = until today.\"\n      }\n     }\n    }\n   }\n  },\n  \"da\": {\n   \"name\": \"Riksbanken renter og valutakurser (SWEA)\",\n   \"publisher\": \"Sveriges riksbank\",\n   \"description\": \"Styringsrenten, markedsrenter og valutakurser fra Riksbankens SWEA-API: en liste over serierne, observationerne for en serie i en periode, den seneste observation og krydskurser mellem to valutaer.\",\n   \"notes\": \"Tjenesten tillader ikke kald fra browseren (ingen CORS), så den nås kun via broen: start broen med --allow-host api.riksbank.se (-AllowHosts api.riksbank.se i PowerShell), forbind den under Hent, og slå Hent via broen til under Internetadgang.\",\n   \"endpoints\": {\n    \"serier\": {\n     \"name\": \"Serier\"\n    },\n    \"observationer\": {\n     \"name\": \"Observationer for en serie\",\n     \"params\": {\n      \"seriesId\": {\n       \"label\": \"Serie\"\n      },\n      \"from\": {\n       \"label\": \"Fra dato\"\n      },\n      \"to\": {\n       \"label\": \"Til dato\",\n       \"help\": \"Tom = til i dag.\"\n      }\n     }\n    },\n    \"senaste\": {\n     \"name\": \"Seneste observation\",\n     \"params\": {\n      \"seriesId\": {\n       \"label\": \"Serie\"\n      }\n     }\n    },\n    \"korskurser\": {\n     \"name\": \"Krydskurser\",\n     \"params\": {\n      \"series1\": {\n       \"label\": \"Første valuta\"\n      },\n      \"series2\": {\n       \"label\": \"Anden valuta\"\n      },\n      \"from\": {\n       \"label\": \"Fra dato\"\n      },\n      \"to\": {\n       \"label\": \"Til dato\",\n       \"help\": \"Tom = til i dag.\"\n      }\n     }\n    }\n   }\n  },\n  \"nb\": {\n   \"name\": \"Riksbanken renter og valutakurser (SWEA)\",\n   \"publisher\": \"Sveriges riksbank\",\n   \"description\": \"Styringsrenten, markedsrenter og valutakurser fra Riksbankens SWEA-API: en liste over seriene, observasjonene for en serie i en periode, den siste observasjonen og krysskurser mellom to valutaer.\",\n   \"notes\": \"Tjenesten tillater ikke kall fra nettleseren (ingen CORS), så den nås bare via broen: start broen med --allow-host api.riksbank.se (-AllowHosts api.riksbank.se i PowerShell), koble den til under Hent inn og slå på Hent via broen under Internettilgang.\",\n   \"endpoints\": {\n    \"serier\": {\n     \"name\": \"Serier\"\n    },\n    \"observationer\": {\n     \"name\": \"Observasjoner for en serie\",\n     \"params\": {\n      \"seriesId\": {\n       \"label\": \"Serie\"\n      },\n      \"from\": {\n       \"label\": \"Fra dato\"\n      },\n      \"to\": {\n       \"label\": \"Til dato\",\n       \"help\": \"Tomt = til i dag.\"\n      }\n     }\n    },\n    \"senaste\": {\n     \"name\": \"Siste observasjon\",\n     \"params\": {\n      \"seriesId\": {\n       \"label\": \"Serie\"\n      }\n     }\n    },\n    \"korskurser\": {\n     \"name\": \"Krysskurser\",\n     \"params\": {\n      \"series1\": {\n       \"label\": \"Første valuta\"\n      },\n      \"series2\": {\n       \"label\": \"Andre valuta\"\n      },\n      \"from\": {\n       \"label\": \"Fra dato\"\n      },\n      \"to\": {\n       \"label\": \"Til dato\",\n       \"help\": \"Tomt = til i dag.\"\n      }\n     }\n    }\n   }\n  },\n  \"nn\": {\n   \"name\": \"Riksbanken renter og valutakursar (SWEA)\",\n   \"publisher\": \"Sveriges riksbank\",\n   \"description\": \"Styringsrenta, marknadsrenter og valutakursar frå SWEA-API-et til Riksbanken: ei liste over seriane, observasjonane for ein serie i ein periode, den siste observasjonen og krysskursar mellom to valutaer.\",\n   \"notes\": \"Tenesta tillèt ikkje kall frå nettlesaren (ingen CORS), så ho blir berre nådd via brua: start brua med --allow-host api.riksbank.se (-AllowHosts api.riksbank.se i PowerShell), kople ho til under Hent og slå på Hent via brua under Internettilgang.\",\n   \"endpoints\": {\n    \"serier\": {\n     \"name\": \"Seriar\"\n    },\n    \"observationer\": {\n     \"name\": \"Observasjonar for ein serie\",\n     \"params\": {\n      \"seriesId\": {\n       \"label\": \"Serie\"\n      },\n      \"from\": {\n       \"label\": \"Frå dato\"\n      },\n      \"to\": {\n       \"label\": \"Til dato\",\n       \"help\": \"Tomt = til i dag.\"\n      }\n     }\n    },\n    \"senaste\": {\n     \"name\": \"Siste observasjon\",\n     \"params\": {\n      \"seriesId\": {\n       \"label\": \"Serie\"\n      }\n     }\n    },\n    \"korskurser\": {\n     \"name\": \"Krysskursar\",\n     \"params\": {\n      \"series1\": {\n       \"label\": \"Første valuta\"\n      },\n      \"series2\": {\n       \"label\": \"Andre valuta\"\n      },\n      \"from\": {\n       \"label\": \"Frå dato\"\n      },\n      \"to\": {\n       \"label\": \"Til dato\",\n       \"help\": \"Tomt = til i dag.\"\n      }\n     }\n    }\n   }\n  },\n  \"fi\": {\n   \"name\": \"Riksbankin korot ja valuuttakurssit (SWEA)\",\n   \"publisher\": \"Sveriges riksbank\",\n   \"description\": \"Ohjauskorko, markkinakorot ja valuuttakurssit Riksbankin SWEA-rajapinnasta: sarjojen luettelo, sarjan havainnot aikaväliltä, viimeisin havainto ja kahden valuutan ristikurssit.\",\n   \"notes\": \"Palvelu ei salli kutsuja selaimesta (ei CORSia), joten sen tavoittaa vain sillan kautta: käynnistä silta valinnalla --allow-host api.riksbank.se (PowerShellissä -AllowHosts api.riksbank.se), yhdistä se kohdassa Tuo ja kytke Hae sillan kautta päälle kohdassa Internetyhteys.\",\n   \"endpoints\": {\n    \"serier\": {\n     \"name\": \"Sarjat\"\n    },\n    \"observationer\": {\n     \"name\": \"Sarjan havainnot\",\n     \"params\": {\n      \"seriesId\": {\n       \"label\": \"Sarja\"\n      },\n      \"from\": {\n       \"label\": \"Alkupäivä\"\n      },\n      \"to\": {\n       \"label\": \"Loppupäivä\",\n       \"help\": \"Tyhjä = tähän päivään.\"\n      }\n     }\n    },\n    \"senaste\": {\n     \"name\": \"Viimeisin havainto\",\n     \"params\": {\n      \"seriesId\": {\n       \"label\": \"Sarja\"\n      }\n     }\n    },\n    \"korskurser\": {\n     \"name\": \"Ristikurssit\",\n     \"params\": {\n      \"series1\": {\n       \"label\": \"Ensimmäinen valuutta\"\n      },\n      \"series2\": {\n       \"label\": \"Toinen valuutta\"\n      },\n      \"from\": {\n       \"label\": \"Alkupäivä\"\n      },\n      \"to\": {\n       \"label\": \"Loppupäivä\",\n       \"help\": \"Tyhjä = tähän päivään.\"\n      }\n     }\n    }\n   }\n  },\n  \"is\": {\n   \"name\": \"Vextir og gengi Riksbanken (SWEA)\",\n   \"publisher\": \"Sveriges riksbank\",\n   \"description\": \"Stýrivextir, markaðsvextir og gengi úr SWEA-API Riksbanken: listi yfir raðirnar, athuganir raðar á tímabili, nýjasta athugunin og krossgengi milli tveggja gjaldmiðla.\",\n   \"notes\": \"Þjónustan leyfir ekki köll úr vafranum (ekkert CORS), svo hún næst aðeins um brúna: ræstu brúna með --allow-host api.riksbank.se (-AllowHosts api.riksbank.se í PowerShell), tengdu hana undir Sækja og kveiktu á Sækja um brúna undir Netaðgangur.\",\n   \"endpoints\": {\n    \"serier\": {\n     \"name\": \"Raðir\"\n    },\n    \"observationer\": {\n     \"name\": \"Athuganir raðar\",\n     \"params\": {\n      \"seriesId\": {\n       \"label\": \"Röð\"\n      },\n      \"from\": {\n       \"label\": \"Frá dagsetningu\"\n      },\n      \"to\": {\n       \"label\": \"Til dagsetningar\",\n       \"help\": \"Tómt = til dagsins í dag.\"\n      }\n     }\n    },\n    \"senaste\": {\n     \"name\": \"Nýjasta athugun\",\n     \"params\": {\n      \"seriesId\": {\n       \"label\": \"Röð\"\n      }\n     }\n    },\n    \"korskurser\": {\n     \"name\": \"Krossgengi\",\n     \"params\": {\n      \"series1\": {\n       \"label\": \"Fyrri gjaldmiðill\"\n      },\n      \"series2\": {\n       \"label\": \"Seinni gjaldmiðill\"\n      },\n      \"from\": {\n       \"label\": \"Frá dagsetningu\"\n      },\n      \"to\": {\n       \"label\": \"Til dagsetningar\",\n       \"help\": \"Tómt = til dagsins í dag.\"\n      }\n     }\n    }\n   }\n  }\n }\n}\n");
